insert into public.events ("id", "slug", "name", "category", "short_description", "description", "poster_url", "event_date", "start_time", "end_time", "venue", "participation", "team_min", "team_max", "fee", "deadline", "rules", "eligibility", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "capacity", "extra_questions", "sort_order", "is_sample") values ('e0000000-0000-4000-8000-000000000001', 'forensic-case-challenge', 'Forensic Case Challenge', 'competition', 'A staged wildlife-crime scene. Read the evidence, reconstruct the story, name the culprit.', 'Teams step into a mock wildlife crime scene and work through evidence stations — hair, feathers, pugmark casts and lab reports — to reconstruct what happened. Judged on reasoning, accuracy and presentation. (Sample description — replace with the real brief.)', '', '2026-12-02', '11:00', '13:00', 'Zoology Lab 1 (placeholder)', 'team', 2, 3, null, '2026-11-30T23:59:00+05:30', '["Teams of 2–3 members (sample rule).","No phones or internet during the challenge.","Evidence must not be removed from stations."]'::jsonb, 'Undergraduate and postgraduate students (placeholder).', 'Coordinator name (placeholder)', '+91 00000 00000', 'events@example.com', true, true, 20, '[{"id":"experience","label":"Has anyone on the team done a forensics course before?","type":"select","options":["Yes","No"],"required":true}]'::jsonb, 0, true) on conflict (id) do nothing;
insert into public.events ("id", "slug", "name", "category", "short_description", "description", "poster_url", "event_date", "start_time", "end_time", "venue", "participation", "team_min", "team_max", "fee", "deadline", "rules", "eligibility", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "capacity", "extra_questions", "sort_order", "is_sample") values ('e0000000-0000-4000-8000-000000000002', 'wildlife-quiz', 'Wildlife Quiz', 'quiz', 'From animal behaviour to conservation history — a fast-paced quiz for the curious.', 'A written preliminary round followed by an on-stage final with audio, visual and rapid-fire rounds. (Sample description.)', '', '2026-12-02', '14:00', '15:30', 'Seminar Hall (placeholder)', 'team', 2, 2, null, '2026-11-30T23:59:00+05:30', '["Teams of exactly 2 (sample rule).","Quizmaster''s decision is final."]'::jsonb, 'Open to all students (placeholder).', 'Coordinator name (placeholder)', '+91 00000 00000', 'events@example.com', true, true, null, '[]'::jsonb, 1, true) on conflict (id) do nothing;
insert into public.events ("id", "slug", "name", "category", "short_description", "description", "poster_url", "event_date", "start_time", "end_time", "venue", "participation", "team_min", "team_max", "fee", "deadline", "rules", "eligibility", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "capacity", "extra_questions", "sort_order", "is_sample") values ('e0000000-0000-4000-8000-000000000003', 'wildlife-photography', 'Through the Lens — Wildlife Photography', 'creative', 'Submit your best frames of wild life — from backyard insects to birds in flight.', 'An online-submission photography contest. Ethical wildlife photography only: no baiting, no disturbing nests. (Sample description.)', '', '2026-12-02', '10:00', '17:00', 'Online submission + exhibition (placeholder)', 'individual', 1, 1, null, '2026-11-30T23:59:00+05:30', '["Maximum 3 entries per person (sample).","Minimal editing only; no composites.","Photos must be your own."]'::jsonb, 'Open to all students (placeholder).', 'Coordinator name (placeholder)', '+91 00000 00000', 'events@example.com', true, true, null, '[{"id":"camera","label":"What will you shoot with?","type":"select","options":["Phone","DSLR / Mirrorless","Other"],"required":false}]'::jsonb, 2, true) on conflict (id) do nothing;
insert into public.events ("id", "slug", "name", "category", "short_description", "description", "poster_url", "event_date", "start_time", "end_time", "venue", "participation", "team_min", "team_max", "fee", "deadline", "rules", "eligibility", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "capacity", "extra_questions", "sort_order", "is_sample") values ('e0000000-0000-4000-8000-000000000004', 'poster-presentation', 'Scientific Poster Presentation', 'competition', 'Present research or a review on biodiversity, conservation or animal science.', 'Display a scientific poster and defend it before a panel of judges. Topics around the festival themes are encouraged. (Sample description.)', '', '2026-12-02', '11:00', '13:00', 'Exhibition Corridor (placeholder)', 'team', 1, 2, null, '2026-11-30T23:59:00+05:30', '["Poster size: [placeholder].","Abstract to be submitted before the deadline.","Max 2 presenters."]'::jsonb, 'UG / PG students (placeholder).', 'Coordinator name (placeholder)', '+91 00000 00000', 'events@example.com', true, true, null, '[{"id":"title","label":"Working title of your poster","type":"text","required":true}]'::jsonb, 3, true) on conflict (id) do nothing;
insert into public.events ("id", "slug", "name", "category", "short_description", "description", "poster_url", "event_date", "start_time", "end_time", "venue", "participation", "team_min", "team_max", "fee", "deadline", "rules", "eligibility", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "capacity", "extra_questions", "sort_order", "is_sample") values ('e0000000-0000-4000-8000-000000000006', 'biodiversity-trail-hunt', 'Biodiversity Trail Hunt', 'game', 'A campus-wide trail of clues, tracks and riddles. Fastest pack wins.', 'Follow footprints, decode clues and spot hidden species across the campus. (Sample description.)', '', '2026-12-02', '14:00', '16:00', 'Campus grounds (placeholder)', 'team', 3, 4, null, '2026-11-30T23:59:00+05:30', '["Teams of 3–4 (sample).","Stay within campus boundaries.","Do not disturb plants or animals."]'::jsonb, 'Open to all students (placeholder).', 'Coordinator name (placeholder)', '+91 00000 00000', 'events@example.com', true, true, null, '[]'::jsonb, 4, true) on conflict (id) do nothing;
insert into public.events ("id", "slug", "name", "category", "short_description", "description", "poster_url", "event_date", "start_time", "end_time", "venue", "participation", "team_min", "team_max", "fee", "deadline", "rules", "eligibility", "coordinator_name", "coordinator_phone", "coordinator_email", "registration_open", "visible", "capacity", "extra_questions", "sort_order", "is_sample") values ('e0000000-0000-4000-8000-000000000007', 'wild-canvas', 'Wild Canvas — Sketch & Paint', 'creative', 'Bring endangered species to life on paper. Theme revealed on the spot.', 'An on-the-spot art event. Participants bring their own materials; paper will be provided. (Sample description.)', '', '2026-12-02', '14:00', '16:00', 'Studio Room (placeholder)', 'individual', 1, 1, null, '2026-11-30T23:59:00+05:30', '["Bring your own colours (sample).","Theme announced at the start."]'::jsonb, 'Open to all students (placeholder).', 'Coordinator name (placeholder)', '+91 00000 00000', 'events@example.com', true, true, null, '[{"id":"medium","label":"Preferred medium","type":"select","options":["Pencil / Charcoal","Watercolour","Acrylic","Mixed media"],"required":false}]'::jsonb, 5, true) on conflict (id) do nothing;
