insert into public.announcements ("id", "title", "body", "published_on", "pinned", "visible", "sort_order") values ('a0000000-0000-4000-8000-000000000001', 'Registrations are open', 'Pick your events and register online — individual and team registrations are both supported. Replace this text from Admin → Announcements.', '2026-10-20', true, true, 0) on conflict (id) do nothing;
insert into public.announcements ("id", "title", "body", "published_on", "pinned", "visible", "sort_order") values ('a0000000-0000-4000-8000-000000000002', 'Save the date: 2 December 2026 · SVKM''s Mithibai College', 'ANIMAUX 2026 — Echoes of the Wild — is a one-day festival hosted by the Department of Zoology. Event timings and the brochure will be published here.', '2026-10-21', false, true, 1) on conflict (id) do nothing;
