insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000001', 'How do I register?', 'Open the Events page, choose an event and press “Register Now”. Fill in the short form and you will instantly receive a unique registration ID on screen (and by email, once email is enabled). No account is needed.', true, 0) on conflict (id) do nothing;
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000002', 'Can I participate in multiple events?', 'Yes. Register separately for each event — the form remembers your details on your device so the next registration takes seconds. Please check the schedule to avoid clashing timings.', true, 1) on conflict (id) do nothing;
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000003', 'Can students from other colleges participate?', 'Eligibility is listed on every event card. [Placeholder — confirm the inter-college policy with the organizing committee.]', true, 2) on conflict (id) do nothing;
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000004', 'Are there registration fees?', 'Fees, if any, are shown on each event card. Events marked “Fee: TBA” are still being finalised. [Placeholder — add payment instructions here once confirmed.]', true, 3) on conflict (id) do nothing;
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000005', 'How do team registrations work?', 'The team leader registers once for the whole team, enters a team name and the details of every member. Team size limits are shown on the event card. Each person should appear in only one team per event.', true, 4) on conflict (id) do nothing;
insert into public.faqs ("id", "question", "answer", "visible", "sort_order") values ('fa000000-0000-4000-8000-000000000006', 'How do I contact an event coordinator?', 'Every event card lists its coordinator. You can also use the Help Desk form on the Contact page — choose the event as your enquiry category and we will route it.', true, 5) on conflict (id) do nothing;
insert into public.festival_settings (id, data) values (1, '{"name":"ANIMAUX","edition":"2026","theme":"Echoes of the Wild","tagline":"Every footprint tells a story. Every species deserves a future.","manifesto":"Where the wilderness speaks, science investigates, and every species has a story.","startDate":"2026-12-02T09:00:00+05:30","endDate":"2026-12-02T18:00:00+05:30","datesConfirmed":true,"department":"Department of Zoology","college":"SVKM''s Mithibai College","address":"Vile Parle (West), Mumbai 400056 — confirm full address","mapEmbedUrl":"https://www.google.com/maps?q=Mithibai+College,+Vile+Parle+West,+Mumbai&output=embed","mapLink":"https://www.google.com/maps/search/?api=1&query=Mithibai+College+Vile+Parle+West+Mumbai","email":"animaux@example.com","phone":"+91 00000 00000","whatsapp":"","instagram":"","brochureUrl":"","registrationsOpen":true,"guidelines":["Carry your college ID card and your ANIMAUX registration ID.","Report to the event venue at least 15 minutes before your event begins.","Teams must be registered by the team leader; one registration per team.","Live animals and animal products are not permitted on campus as exhibits.","Crime-scene props and evidence at forensic events are for investigation only — look, note, don’t touch unless told.","The decision of the judges and organizing committee is final.","[Add or edit guidelines from Admin → Festival settings]"]}'::jsonb) on conflict (id) do nothing;
